import{_ as s,o as e,c as t,a5 as i}from"./chunks/framework.DJo0M80U.js";const b=JSON.parse('{"title":"57. Static and Shared Libraries","description":"The Little Book of C — 57. Static and Shared Libraries","frontmatter":{"title":"57. Static and Shared Libraries","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Compilation and Build"],"description":"The Little Book of C — 57. Static and Shared Libraries","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":57,"sidebarWeight":57,"lang":"en-US","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/057-Static and Shared Libraries","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/057-Static and Shared Libraries"},"headers":[],"relativePath":"posts/c教程/en-US/06-Compilation and Build/057-Static and Shared Libraries.md","filePath":"posts/c教程/en-US/06-Compilation and Build/057-Static and Shared Libraries.md","lastUpdated":1790163617000}'),n={name:"posts/c教程/en-US/06-Compilation and Build/057-Static and Shared Libraries.md"};function p(l,a,o,d,c,r){return e(),t("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/06-编译与构建/057-Static and Shared Libraries)</p><p>In large C projects, you often want to reuse code across multiple programs, without copying the same<code>.c</code> files everywhere. That’s exactly what libraries are for.</p><p>A library is a collection of precompiled object files (<code>.o</code>) packaged together. There are two main kinds:</p><table tabindex="0"><thead><tr><th>Type</th><th>Extension</th><th>Loaded</th><th>Typical Use</th></tr></thead><tbody><tr><td>Static Library</td><td><code>.a</code></td><td>At compile time</td><td>Simpler, self-contained executables</td></tr><tr><td>Shared Library</td><td><code>.so</code></td><td>At runtime</td><td>Smaller binaries, reusable system-wide</td></tr></tbody></table><p>Let’s see how to build and use both.</p><h4 id="step-1-build-a-static-library-a" tabindex="-1">Step 1. Build a Static Library (.a) <a class="header-anchor" href="#step-1-build-a-static-library-a" aria-label="Permalink to &quot;Step 1. Build a Static Library (.a)&quot;">​</a></h4><p>A static library is just an archive of object files.</p><p>Example project:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>math.c</span></span>
<span class="line"><span>string_utils.c</span></span>
<span class="line"><span>main.c</span></span></code></pre></div><p>math.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int mul(int a, int b) { return a * b; }</span></span></code></pre></div><p>string_utils.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int str_eq(const char *a, const char *b) {</span></span>
<span class="line"><span>    return strcmp(a, b) == 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>math.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int mul(int a, int b);</span></span></code></pre></div><p>string_utils.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int str_eq(const char *a, const char *b);</span></span></code></pre></div><p>Compile the object files:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c math.c string_utils.c</span></span></code></pre></div><p>Create a static library:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ar rcs libmylib.a math.o string_utils.o</span></span></code></pre></div><p>Now you have<code>libmylib.a</code>, your first static library.</p><h4 id="step-2-link-the-library" tabindex="-1">Step 2. Link the Library <a class="header-anchor" href="#step-2-link-the-library" aria-label="Permalink to &quot;Step 2. Link the Library&quot;">​</a></h4><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>#include &quot;string_utils.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;3 + 4 = %d\\n&quot;, add(3, 4));</span></span>
<span class="line"><span>    printf(&quot;Equal? %d\\n&quot;, str_eq(&quot;abc&quot;, &quot;abc&quot;));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Link it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -L. -lmylib -o app</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3 + 4 = 7</span></span>
<span class="line"><span>Equal? 1</span></span></code></pre></div><p>Here:</p><ul><li><code>-L.</code> tells the compiler to look in the current directory</li><li><code>-lmylib</code> links against<code>libmylib.a</code></li></ul><p>The<code>.a</code> file is copied into your executable, you can now delete it and your program will still run.</p><h4 id="step-3-inspect-the-static-library" tabindex="-1">Step 3. Inspect the Static Library <a class="header-anchor" href="#step-3-inspect-the-static-library" aria-label="Permalink to &quot;Step 3. Inspect the Static Library&quot;">​</a></h4><p>List its contents:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ar -t libmylib.a</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>math.o</span></span>
<span class="line"><span>string_utils.o</span></span></code></pre></div><p>Extract a file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ar -x libmylib.a math.o</span></span></code></pre></div><p>You can think of<code>.a</code> files like a “.zip” of<code>.o</code> modules.</p><h4 id="step-4-build-a-shared-library-so" tabindex="-1">Step 4. Build a Shared Library (.so) <a class="header-anchor" href="#step-4-build-a-shared-library-so" aria-label="Permalink to &quot;Step 4. Build a Shared Library (.so)&quot;">​</a></h4><p>A shared library is loaded dynamically at runtime, not compiled into the executable. They’re what you see in<code>/usr/lib</code> as<code>.so</code>(Linux) or<code>.dll</code>(Windows).</p><p>Build one:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -fPIC -c math.c string_utils.c</span></span>
<span class="line"><span>gcc -shared -o libmylib.so math.o string_utils.o</span></span></code></pre></div><p>Now you have a shared library:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>libmylib.so</span></span></code></pre></div><p><code>-fPIC</code> means “position-independent code”, required for shared libraries.</p><h4 id="step-5-link-a-program-against-it" tabindex="-1">Step 5. Link a Program Against It <a class="header-anchor" href="#step-5-link-a-program-against-it" aria-label="Permalink to &quot;Step 5. Link a Program Against It&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -L. -lmylib -o app</span></span></code></pre></div><p>Run it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./app</span></span></code></pre></div><p>If you get:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error while loading shared libraries: libmylib.so: cannot open shared object file</span></span></code></pre></div><p>You need to add the current directory to the runtime library path:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export LD_LIBRARY_PATH=.</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3 + 4 = 7</span></span>
<span class="line"><span>Equal? 1</span></span></code></pre></div><h4 id="step-6-verify-the-linking-type" tabindex="-1">Step 6. Verify the Linking Type <a class="header-anchor" href="#step-6-verify-the-linking-type" aria-label="Permalink to &quot;Step 6. Verify the Linking Type&quot;">​</a></h4><p>Check whether your program is statically or dynamically linked:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ldd app</span></span></code></pre></div><p>Output for dynamic linking:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>libmylib.so =&gt; ./libmylib.so (0x00007f8e8b...)</span></span>
<span class="line"><span>libc.so.6 =&gt; /lib/x86_64-linux-gnu/libc.so.6 (...)</span></span></code></pre></div><p>For static linking,<code>libmylib.a</code> won’t appear, it’s baked into the executable.</p><h4 id="step-7-installing-libraries-system-wide" tabindex="-1">Step 7. Installing Libraries System-Wide <a class="header-anchor" href="#step-7-installing-libraries-system-wide" aria-label="Permalink to &quot;Step 7. Installing Libraries System-Wide&quot;">​</a></h4><p>To make your library accessible globally:</p><p>Copy the<code>.so</code> file to<code>/usr/local/lib</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cp libmylib.so /usr/local/lib</span></span>
<span class="line"><span>sudo ldconfig</span></span></code></pre></div><p>Copy headers to<code>/usr/local/include</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cp math.h string_utils.h /usr/local/include</span></span></code></pre></div><p>Now you can compile anywhere with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -lmylib -o app</span></span></code></pre></div><h4 id="step-8-versioning-shared-libraries" tabindex="-1">Step 8. Versioning Shared Libraries <a class="header-anchor" href="#step-8-versioning-shared-libraries" aria-label="Permalink to &quot;Step 8. Versioning Shared Libraries&quot;">​</a></h4><p>Real-world shared libraries include version numbers for compatibility:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>libmylib.so.1.0.0</span></span>
<span class="line"><span>libmylib.so -&gt; libmylib.so.1.0.0  (symlink)</span></span></code></pre></div><p>You can set this during build:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -shared -Wl,-soname,libmylib.so.1 -o libmylib.so.1.0.0 math.o string_utils.o</span></span>
<span class="line"><span>ln -sf libmylib.so.1.0.0 libmylib.so</span></span></code></pre></div><h4 id="tiny-code-combined-example" tabindex="-1">Tiny Code: Combined Example <a class="header-anchor" href="#tiny-code-combined-example" aria-label="Permalink to &quot;Tiny Code: Combined Example&quot;">​</a></h4><p>Makefile</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -fPIC</span></span>
<span class="line"><span>OBJS = math.o string_utils.o</span></span>
<span class="line"><span>TARGET_STATIC = libmylib.a</span></span>
<span class="line"><span>TARGET_SHARED = libmylib.so</span></span>
<span class="line"><span>all: $(TARGET_STATIC) $(TARGET_SHARED)</span></span>
<span class="line"><span>$(TARGET_STATIC): $(OBJS)</span></span>
<span class="line"><span>    ar rcs $@ $^</span></span>
<span class="line"><span>$(TARGET_SHARED): $(OBJS)</span></span>
<span class="line"><span>    $(CC) -shared -o $@ $^</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJS) $(TARGET_STATIC) $(TARGET_SHARED)</span></span></code></pre></div><p>Build:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><p>Link app:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -L. -lmylib -o app</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LD_LIBRARY_PATH=. ./app</span></span></code></pre></div><h4 id="step-9-static-vs-shared-tradeoffs" tabindex="-1">Step 9. Static vs Shared Tradeoffs <a class="header-anchor" href="#step-9-static-vs-shared-tradeoffs" aria-label="Permalink to &quot;Step 9. Static vs Shared Tradeoffs&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Feature</th><th>Static (<code>.a</code>)</th><th>Shared (<code>.so</code>)</th></tr></thead><tbody><tr><td>Linking</td><td>At compile time</td><td>At runtime</td></tr><tr><td>File size</td><td>Larger executable</td><td>Smaller executable</td></tr><tr><td>Update</td><td>Recompile required</td><td>Replace<code>.so</code> file</td></tr><tr><td>Portability</td><td>Fully self-contained</td><td>Needs library present</td></tr><tr><td>Speed</td><td>Slightly faster</td><td>Slight load delay</td></tr></tbody></table><p>For small tools or embedded systems, use static. For large or updatable software, prefer shared.</p><h4 id="step-10-inspecting-library-symbols" tabindex="-1">Step 10. Inspecting Library Symbols <a class="header-anchor" href="#step-10-inspecting-library-symbols" aria-label="Permalink to &quot;Step 10. Inspecting Library Symbols&quot;">​</a></h4><p>To see what functions are exported:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm -D libmylib.so | grep add</span></span></code></pre></div><p>To check dynamic symbol resolution:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>objdump -T libmylib.so | head</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Libraries make your C code modular, maintainable, and reusable. They are the foundation of every serious C ecosystem, from<code>libc</code> to OpenSSL to SDL.</p><p>Once you understand how to build and link your own<code>.a</code> and<code>.so</code> files, you can:</p><ul><li>Ship APIs others can use</li><li>Organize large codebases cleanly</li><li>Understand how system libraries integrate into every program you compile</li></ul><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Build a small math library (<code>libmathx.a</code>,<code>libmathx.so</code>).</li><li>Create a header-only helper and test it in multiple programs.</li><li>Try mixing static and shared libraries in one build.</li><li>Inspect your shared library with<code>ldd</code> and<code>nm</code>.</li><li>Version your<code>.so</code> file using symbolic links and test compatibility.</li></ol><p>Next, you’ll explore how compiler flags and optimization levels affect performance, safety, and debugging, learning how to tune<code>gcc</code> for both development and release builds.</p>`,100)])])}const u=s(n,[["render",p]]);export{b as __pageData,u as default};
